const http=require('http');const crypto=require('crypto');const {URL}=require('url');
const publicPort=Number(process.env.PORT||10000);const internalPort=publicPort+1;process.env.PORT=String(internalPort);require('./server.js');
const RESOURCES=new Set(['manifest.json','catalog','meta','stream']);const PUBLIC=new Set(['configure','health','xtream-health','artwork','qr']);const SECRET=process.env.XSPORTSX_CONFIG_SECRET||'change-this-xsportsx-secret-in-render';const KEY=crypto.createHash('sha256').update(SECRET).digest();const BUILD_VERSION='8.4.0';
const LEAGUES={nfl:['NFL','🏈'],ncaaf:['NCAA Football','🏈'],nba:['NBA','🏀'],wnba:['WNBA','🏀'],ncaab:['NCAA Basketball','🏀'],mlb:['MLB','⚾'],nhl:['NHL','🏒'],mls:['MLS','⚽'],epl:['Premier League','⚽'],ucl:['UEFA Champions League','⚽'],laliga:['LaLiga','⚽'],seriea:['Serie A','⚽'],bundesliga:['Bundesliga','⚽'],ligue1:['Ligue 1','⚽'],ufc:['UFC','🥊'],boxing:['Boxing','🥊']};
const ALIASES={nfl:['nfl'],ncaaf:['ncaaf','ncaafb','ncaa football','college football','college-football'],nba:['nba'],wnba:['wnba'],ncaab:['ncaab','ncaamb','ncaa basketball','college basketball','mens-college-basketball'],mlb:['mlb'],nhl:['nhl'],mls:['mls'],epl:['epl','premier league','english premier league'],ucl:['ucl','uefa champions league','champions league'],laliga:['laliga','la liga'],seriea:['seriea','serie a'],bundesliga:['bundesliga'],ligue1:['ligue1','ligue 1'],ufc:['ufc','mma'],boxing:['boxing','box']};
function decrypt(t){try{const[a,b,c]=String(t||'').split('.');if(!a||!b||!c)return null;const d=crypto.createDecipheriv('aes-256-gcm',KEY,Buffer.from(a,'base64url'));d.setAuthTag(Buffer.from(b,'base64url'));return JSON.parse(Buffer.concat([d.update(Buffer.from(c,'base64url')),d.final()]).toString())}catch{return null}}
function canonical(v){const x=String(v||'').trim().toLowerCase();for(const[id,a]of Object.entries(ALIASES))if(a.includes(x))return id;return null}
function selected(token){const c=decrypt(token);if(!c||!Array.isArray(c.sports)||!c.sports.length)return new Set();return new Set(c.sports.map(canonical).filter(Boolean))}
function tokenFrom(raw){const u=new URL(raw||'/','http://local');let p=u.pathname.split('/').filter(Boolean);if(p[0]==='v527')p=p.slice(1);const i=p.findIndex(x=>RESOURCES.has(x)||x.startsWith('catalog')||x.startsWith('meta')||x.startsWith('stream'));if(i>0)return p[i-1];if(p.length===1&&!PUBLIC.has(p[0])&&!p[0].endsWith('.json'))return p[0];return u.searchParams.get('config')||''}
function rewrite(raw){const u=new URL(raw||'/','http://local');let p=u.pathname.split('/').filter(Boolean);if(p[0]==='v527')p=p.slice(1);const i=p.findIndex(x=>RESOURCES.has(x)||x.startsWith('catalog')||x.startsWith('meta')||x.startsWith('stream'));if(i<0){if(p.length===1&&!PUBLIC.has(p[0])&&!p[0].endsWith('.json')){u.pathname='/manifest.json';u.searchParams.set('config',p[0])}return u.pathname+(u.search||'')}const before=p.slice(0,i);u.pathname='/'+p.slice(i).join('/');if(before.length)u.searchParams.set('config',before[before.length-1]);return u.pathname+(u.search||'')}
function manifest(base,t){const s=selected(t);const catalogs=[...s].filter(x=>LEAGUES[x]).map(id=>({type:'tv',id,name:`${LEAGUES[id][1]} ${LEAGUES[id][0]}`,extra:[],showInHome:true}));return{id:`community.xsportsx.v8.4.${crypto.createHash('sha256').update(String(t)).digest('hex').slice(0,20)}`,version:BUILD_VERSION,name:'XSportsX',description:'XSportsX 8.4.0 private sports connection.',resources:[{name:'catalog',types:['tv']},{name:'meta',types:['tv']},{name:'stream',types:['tv']}],types:['tv'],idPrefixes:['sport:','xtream:'],catalogs,behaviorHints:{configurable:false,configurationRequired:false},logo:`${base}/artwork/other.svg`}}
function configPage(base){const groups=[['FOOTBALL',['nfl','ncaaf']],['BASKETBALL',['nba','wnba','ncaab']],['BASEBALL & HOCKEY',['mlb','nhl']],['SOCCER',['mls','epl','ucl','laliga','seriea','bundesliga','ligue1']],['COMBAT',['ufc','boxing']]];const names=Object.fromEntries(Object.entries(LEAGUES).map(([k,v])=>[k,v]));return `<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1"><meta name="theme-color" content="#050811"><title>XSportsX 8.4 • Configuration</title><style>*{box-sizing:border-box}body{margin:0;background:#03060d;color:#fff;font-family:system-ui,-apple-system,Segoe UI,sans-serif}main{max-width:980px;margin:auto;padding:20px 14px 60px}.top{display:flex;justify-content:space-between;align-items:center}.logo{font-size:29px;font-weight:950;font-style:italic;letter-spacing:2px}.logo b{color:#ff263d}.ver{font-size:11px;border:1px solid #29364c;border-radius:999px;padding:7px 10px;color:#a9b7ca}.hero,.card{margin-top:16px;border:1px solid #172338;border-radius:22px;background:#080d17;padding:20px}.hero{background:linear-gradient(135deg,#101d34,#050910)}h1{font-size:clamp(30px,6vw,48px);line-height:1.03;margin:8px 0}.muted{color:#8290a5}.source{display:flex;gap:8px;margin:12px 0}.source button,.tool{flex:1;padding:13px;border:1px solid #29384e;border-radius:12px;background:#0b1320;color:#dce5f2;font-weight:900}.source .on{background:#2a0d14;border-color:#ff263d}.fields input{width:100%;margin:6px 0;padding:14px;border-radius:12px;border:1px solid #29384e;background:#050a12;color:#fff;font-size:15px}.groups{margin-top:14px}.gtitle{font-size:11px;letter-spacing:1.2px;color:#75849a;font-weight:950;margin:17px 0 8px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.league{position:relative;display:flex;align-items:center;gap:10px;padding:13px;border:1px solid #29384e;border-radius:13px;background:#0a111d;color:#dce5f2;cursor:pointer;user-select:none}.league input{position:absolute;opacity:0;width:1px;height:1px}.box{width:21px;height:21px;border:2px solid #43526a;border-radius:6px;display:grid;place-items:center;flex:none}.league:has(input:checked){border-color:#ff263d;background:#2b0d14}.league input:checked+.box{background:#ff263d;border-color:#ff263d}.league input:checked+.box:after{content:'✓';font-weight:950}.actions{display:flex;gap:8px;margin-top:12px}.tool{cursor:pointer}.count{margin:12px 0;color:#ff6171;font-weight:950}.create{width:100%;margin-top:16px;padding:16px;border:0;border-radius:13px;background:#ff263d;color:#fff;font-weight:950;font-size:15px}.result{display:none;margin-top:14px;padding:16px;border:1px solid #1e7050;border-radius:15px;background:#06151a}.result a{color:#8fc5ff;word-break:break-all}@media(min-width:760px){.grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:500px){.grid{grid-template-columns:1fr}}</style></head><body><main><div class="top"><div class="logo"><b>X</b>SPORTS<b>X</b></div><div class="ver">BUILD ${BUILD_VERSION}</div></div><section class="hero"><div class="muted">PRIVATE SPORTS CONNECTION</div><h1>Your sports.<br>Your IPTV.</h1><p class="muted">Select the exact leagues you want. The private manifest contains only those selections and can be used across your devices.</p></section><section class="card"><h2>1. Source</h2><div class="source"><button id="xb" class="on" type="button">XTREAM</button><button id="mb" type="button">M3U / M3U8</button></div><div id="xf" class="fields"><input id="base" placeholder="Xtream server URL"><input id="user" placeholder="Username"><input id="pass" type="password" placeholder="Password"></div><div id="mf" class="fields" style="display:none"><input id="m3u" placeholder="M3U playlist URL"><input id="epg" placeholder="EPG URL (optional)"></div></section><section class="card"><h2>2. Select leagues</h2><div class="count" id="count">0 selected</div><div class="actions"><button class="tool" id="all" type="button">SELECT ALL</button><button class="tool" id="none" type="button">CLEAR ALL</button></div>${groups.map(([g,ids])=>`<div class="groups"><div class="gtitle">${g}</div><div class="grid">${ids.map(id=>`<label class="league"><input type="checkbox" value="${id}"><span class="box"></span><span>${names[id][1]} ${names[id][0]}</span></label>`).join('')}</div></div>`).join('')}</section><section class="card"><h2>3. Create connection</h2><button class="create" id="go" type="button" disabled>CREATE PRIVATE SPORTS CONNECTION</button><div class="result" id="result"></div></section></main><script>
const q=s=>document.querySelector(s),qa=s=>Array.from(document.querySelectorAll(s));let src='xtream';
function refresh(){const a=qa('input[type=checkbox]:checked');q('#count').textContent=a.length+' selected';q('#go').disabled=!a.length}
qa('input[type=checkbox]').forEach(x=>x.addEventListener('change',refresh));q('#all').addEventListener('click',()=>{qa('input[type=checkbox]').forEach(x=>x.checked=true);refresh()});q('#none').addEventListener('click',()=>{qa('input[type=checkbox]').forEach(x=>x.checked=false);refresh()});
q('#xb').addEventListener('click',()=>{src='xtream';q('#xb').classList.add('on');q('#mb').classList.remove('on');q('#xf').style.display='block';q('#mf').style.display='none'});q('#mb').addEventListener('click',()=>{src='m3u';q('#mb').classList.add('on');q('#xb').classList.remove('on');q('#xf').style.display='none';q('#mf').style.display='block'});
q('#go').addEventListener('click',async()=>{const sports=qa('input[type=checkbox]:checked').map(x=>x.value);const body={source:src,sports};if(src==='xtream')body.xtream={baseUrl:q('#base').value,username:q('#user').value,password:q('#pass').value};else{body.m3uUrl=q('#m3u').value;body.epgUrl=q('#epg').value}const r=q('#result');r.style.display='block';r.textContent='Creating connection…';try{const z=await fetch('${base}/configure',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)}),d=await z.json();if(!z.ok)throw Error(d.error||'Configuration failed');r.innerHTML='<b>✓ '+sports.length+' LEAGUES LOCKED</b><p>Install this manifest in Nuvio:</p><a href="'+d.manifestUrl+'">'+d.manifestUrl+'</a>'}catch(e){r.textContent=e.message}});refresh();
</script></body></html>`}
const proxy=http.createServer((req,res)=>{try{const token=tokenFrom(req.url);const path=rewrite(req.url);const parsed=new URL(path,'http://local').pathname;const base=`${String(req.headers['x-forwarded-proto']||'https').split(',')[0]}://${req.headers.host||'localhost'}`;if(req.method==='GET'&&parsed==='/configure'){const body=configPage(base);res.writeHead(200,{'content-type':'text/html; charset=utf-8','cache-control':'no-store, no-cache, must-revalidate, proxy-revalidate','pragma':'no-cache','x-xsportsx-build':BUILD_VERSION,'content-length':Buffer.byteLength(body)});return res.end(body)}if(req.method==='GET'&&parsed==='/manifest.json'&&token){const s=selected(token);if(!s.size){res.writeHead(400,{'content-type':'application/json','cache-control':'no-store','x-xsportsx-build':BUILD_VERSION});return res.end(JSON.stringify({error:'Invalid or empty private sports selection'}))}const body=JSON.stringify(manifest(base,token));res.writeHead(200,{'content-type':'application/json; charset=utf-8','content-length':Buffer.byteLength(body),'cache-control':'no-store, no-cache, must-revalidate, proxy-revalidate','x-xsportsx-build':BUILD_VERSION,'x-xsportsx-selected-leagues':[...s].join(',')});return res.end(body)}const upstream=http.request({hostname:'127.0.0.1',port:internalPort,path,method:req.method,headers:{...req.headers,host:`127.0.0.1:${internalPort}`}},response=>{const h={...response.headers,'x-xsportsx-build':BUILD_VERSION};if(parsed==='/configure'){h['cache-control']='no-store'}res.writeHead(response.statusCode||502,h);response.pipe(res)});upstream.on('error',e=>{res.statusCode=502;res.end(`XSportsX bootstrap error: ${e.message}`)});req.pipe(upstream)}catch(e){res.statusCode=400;res.end(e.message)}});proxy.listen(publicPort,'0.0.0.0',()=>console.log(`XSportsX ${BUILD_VERSION} public ${publicPort} app ${internalPort}`));
